import {httpStream} from './stream.js';
import {mountShell} from './reference.js';
import {escapeHTML as safe} from './stream.js';
import {symbol} from './site-shell.js';

const steps=['Profile','Basic Settings','Intro'];
export function normalizeDraft(d,index=0){return {...d,id:d.id||`legacy-${index}`,type:d.type==='character'?'character':'story',title:d.title||'',description:d.description||'',details:d.details||'',prologue:d.prologue||'',opening:d.opening||'',scenario:d.scenario||'Default',guide:d.guide||'',suggestions:Array.isArray(d.suggestions)?d.suggestions.slice(0,3):[]};}
const field=(label,key,value,max,help='',multiline=false)=>`<div class="builder-field"><label for="draft-${key}">${label}</label><button type="button" class="builder-ai-trigger" data-expand-field="${key}">✧ Expand with AI</button>${help?`<p>${help}</p>`:''}${multiline?`<textarea id="draft-${key}" name="${key}" maxlength="${max}" rows="${key==='details'?12:5}">${safe(value)}</textarea>`:`<input id="draft-${key}" name="${key}" maxlength="${max}" value="${safe(value)}">`}<small data-count="${key}">${value.length} / ${max}</small></div>`;

export function showBuilder(path,h){
 if(path!=='/builder'&&!/^\/builder\/(story|character)\/[^/]+$/.test(path))return false;
 document.title='Create a Title · Storylove';
 if(path==='/builder'){
  const root=mountShell(`<div class="builder-choice-screen"><section class="builder-choice" aria-labelledby="builder-title"><header><h1 id="builder-title">Create a Title</h1><a href="/my-title" aria-label="Close creator">${symbol('close')}</a></header><div>${[['story','Story','Content that immerses you into a universe with various characters and adventures.'],['character','Character','Content that develops a relationship with a single character through short and concise dialogues.']].map(([type,label,description])=>`<button data-create-type="${type}"><img src="/assets/${type==='story'?'cover-0.webp':'character-0.webp'}" alt=""><span><strong>${label}</strong><small>${description}</small></span></button>`).join('')}</div></section></div>`,h,'builder');
  root.querySelectorAll('[data-create-type]').forEach(b=>b.onclick=()=>h.navigate(`/builder/${b.dataset.createType}/new`));
  return true;
 }
 const [, ,type,id]=path.split('/');
 const drafts=()=>h.read('ooc-custom',[]).map(normalizeDraft);
 let draft=id==='new'?normalizeDraft({id:`draft-${crypto.randomUUID()}`,type}):drafts().find(d=>d.id===id);
 if(!draft){mountShell('<div class="shell-empty"><h1>Draft unavailable</h1><a href="/my-title">Back to My Titles</a></div>',h,'builder');return true;}
 let step=0,dirty=false,aiController;
 const fieldLimits={title:50,description:50,details:6000,prologue:2000,scenario:25,opening:2000,guide:1000,suggestions:600};
 const root=mountShell(`<div class="builder-editor"><header class="builder-header"><a href="/my-title" aria-label="Back to My Titles">‹</a><h1>${type==='character'?'Character':'Story'}</h1><span data-draft-status role="status">Private draft</span><button data-draft-save aria-label="Save draft">${symbol('book')}<span>Save</span></button><button data-draft-review class="shell-white-button">Review</button></header><div class="builder-layout"><section class="builder-main"><nav class="builder-steps" aria-label="Creation steps">${steps.map((s,i)=>`<button data-builder-step="${i}">${s}<span>*</span></button>`).join('')}</nav><form class="builder-fields" novalidate></form><footer class="builder-controls"><button data-builder-prev>Previous</button><button data-builder-next class="shell-white-button">Next</button></footer></section><aside class="builder-preview"><header><h2>Preview</h2><button data-builder-preview-toggle aria-label="Toggle preview">${symbol('close')}</button></header><div data-draft-preview></div><p>Private draft preview. Publishing is not available yet.</p></aside></div><button class="builder-mobile-preview" data-builder-preview-open>Preview</button></div>`,h,'builder');
 const form=root.querySelector('form'),status=root.querySelector('[data-draft-status]');
 function preview(){root.querySelector('[data-draft-preview]').innerHTML=`<article class="builder-preview-card">${draft.image?`<img src="${safe(draft.image)}" alt="Title cover">`:'<div class="builder-cover-placeholder">'+symbol(type==='story'?'book':'person',48)+'</div>'}<h3>${safe(draft.title||`${type==='story'?'Story':'Character'} Name`)}</h3><p>${safe(draft.description||'One-line introduction')}</p></article><section class="builder-scene"><h3>${safe(draft.scenario)}</h3><p>${safe(draft.prologue||draft.details||'Your story preview will appear here.')}</p><p>${safe(draft.opening)}</p>${draft.suggestions.filter(Boolean).map(s=>`<span>${safe(s)}</span>`).join('')}</section>`;}
 function changed(){dirty=true;status.textContent='Unsaved changes';preview();}
 function saveDraft(){const entries=drafts(),index=entries.findIndex(d=>d.id===draft.id);draft={...draft,updatedAt:Date.now()};if(index<0)entries.push(draft);else entries[index]=draft;try{h.save('ooc-custom',entries);}catch{status.textContent='Unable to save. Device storage may be full.';return false;}dirty=false;status.textContent='Draft saved';if(location.pathname.endsWith('/new'))window.history.replaceState({},'',`/builder/${type}/${draft.id}`);return true;}
 function review(){const missing=[draft.title.trim().length<2?'Title (at least 2 characters)':null,!draft.description.trim()?'One-line introduction':null,!draft.details.trim()?'Story Details':null,!draft.opening.trim()?'Opening Scene':null].filter(Boolean);h.show(`<h2>Review draft</h2>${missing.length?`<p>Complete these fields before your draft is ready:</p><ul>${missing.map(v=>`<li>${v}</li>`).join('')}</ul>`:'<p>Your required fields are complete.</p>'}<p>Publishing is not available yet. You can save and continue editing this private draft.</p><button class="shell-white-button" data-review-save>Save draft</button>`);document.querySelector('[data-review-save]').onclick=()=>{if(saveDraft())document.querySelector('[data-review-save]').closest('dialog').close();};}
 async function expandField(field){
  const current=field==='suggestions'?draft.suggestions.join('\n'):draft[field];
  h.show(`<section class="builder-ai"><h2>Expand ${safe(field)} with AI</h2><p>Give us one sentence. AI will expand it using your draft's language, style and world.</p><label for="ai-idea">Your idea or direction</label><textarea id="ai-idea" maxlength="3000" rows="3">${safe(current||draft.description||draft.title||'')}</textarea><div class="builder-ai-actions"><button class="shell-white-button" data-ai-generate>Generate</button><button data-ai-stop hidden>Stop</button></div><p role="status" data-ai-status></p><label for="ai-result">Review and edit</label><textarea id="ai-result" maxlength="${fieldLimits[field]}" rows="9" placeholder="Your expansion will appear here…"></textarea><button class="shell-white-button" data-ai-apply disabled>Use this text</button><p>Your existing field changes only when you choose Use this text. Cover generation is not connected.</p></section>`);
  const dialog=document.querySelector('#modal'),idea=dialog.querySelector('#ai-idea'),result=dialog.querySelector('#ai-result'),feedback=dialog.querySelector('[data-ai-status]'),generate=dialog.querySelector('[data-ai-generate]'),stop=dialog.querySelector('[data-ai-stop]'),apply=dialog.querySelector('[data-ai-apply]');
  const cancel=()=>aiController?.abort();dialog.addEventListener('close',cancel,{once:true});
  stop.onclick=cancel;result.oninput=()=>{apply.disabled=!result.value.trim()||Boolean(aiController);};
  generate.onclick=async()=>{
   if(!idea.value.trim()){feedback.textContent='Enter one sentence to begin.';idea.focus();return;}
   const controller=new AbortController();aiController=controller;generate.disabled=true;apply.disabled=true;stop.hidden=false;result.value='';feedback.textContent='Connecting to AI…';
   try{for await(const chunk of httpStream([],controller.signal,{task:'author',type,field,idea:idea.value,draft:Object.fromEntries(Object.keys(fieldLimits).map(key=>[key,draft[key]]))},event=>{feedback.textContent=event.phase==='thinking'?'AI is writing…':'Waiting for AI…';})){if(!dialog.open||!root.isConnected){controller.abort();break;}result.value=(result.value+chunk).slice(0,fieldLimits[field]);feedback.textContent='Generating…';}feedback.textContent=controller.signal.aborted?'Stopped. Review the partial text or try again.':'Ready. Review the text before using it.';}
   catch(error){feedback.textContent=controller.signal.aborted?'Stopped. You can try again.':error.message||'Generation failed. Please try again.';}
   finally{if(aiController===controller)aiController=null;generate.disabled=false;stop.hidden=true;apply.disabled=!result.value.trim();}
  };
  apply.onclick=()=>{if(aiController||!result.value.trim())return;if(field==='suggestions')draft.suggestions=result.value.split('\n').map(v=>v.replace(/^[-*\d.)\s]+/,'').trim()).filter(Boolean).slice(0,3).map(v=>v.slice(0,200));else draft[field]=result.value.trim().slice(0,fieldLimits[field]);changed();renderStep();dialog.close();};
 }
 function renderStep(){
  root.querySelectorAll('[data-builder-step]').forEach((b,i)=>{b.setAttribute('aria-current',i===step?'step':'false');});
  root.querySelector('[data-builder-prev]').disabled=step===0;root.querySelector('[data-builder-next]').textContent=step===steps.length-1?'Review':'Next';
  form.innerHTML=step===0?`<div class="builder-field"><label for="draft-image">Title Image</label><p>Upload an image (up to 5MB). Images stay with your private draft.</p><label class="builder-upload" for="draft-image">${draft.image?`<img src="${safe(draft.image)}" alt="Title cover">`:symbol('person',32)}<span>Upload</span></label><input id="draft-image" type="file" accept="image/png,image/jpeg,image/webp"><p data-image-error role="alert"></p></div>`+field(type==='character'?'Character Name':'Story Name','title',draft.title,50,'Enter 2–50 characters.')+field('One-line introduction','description',draft.description,50,'',true):step===1?field(type==='character'?'Character Details':'Story Details','details',draft.details,6000,'Describe the universe, characters, setting, mission, and conflicts of your story.',true):field('Prologue','prologue',draft.prologue,2000,'Please write the prologue of the story.',true)+field('Starting Scenario Name','scenario',draft.scenario,25,'Choose the name of this starting scenario.')+field('Opening Scene','opening',draft.opening,2000,'Describe the situation where the story begins.',true)+field('Play Guide','guide',draft.guide,1000,'Only visible to the user; this does not affect AI context.',true)+`<div class="builder-field"><label>Response Suggestions</label><button type="button" class="builder-ai-trigger" data-expand-field="suggestions">✧ Generate with AI</button><p>Add suggested actions for users to start with (up to 3).</p>${[0,1,2].map(i=>`<input aria-label="Response suggestion ${i+1}" data-suggestion="${i}" maxlength="200" value="${safe(draft.suggestions[i]||'')}" placeholder="Suggested response ${i+1}">`).join('')}</div>`;
  form.querySelectorAll('[name]').forEach(input=>input.oninput=()=>{draft[input.name]=input.value;form.querySelector(`[data-count="${input.name}"]`).textContent=`${input.value.length} / ${input.maxLength}`;changed();});
  form.querySelectorAll('[data-suggestion]').forEach(input=>input.oninput=()=>{draft.suggestions[Number(input.dataset.suggestion)]=input.value;changed();});
  const upload=form.querySelector('[type=file]');if(upload)upload.onchange=async()=>{const file=upload.files?.[0];if(!file)return;const error=form.querySelector('[data-image-error]');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){error.textContent='Choose a PNG, JPEG or WebP image up to 5MB.';upload.value='';return;}try{const image=await createImageBitmap(file),canvas=document.createElement('canvas');const scale=Math.min(1,640/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();draft.image=canvas.toDataURL('image/webp',.8);changed();renderStep();}catch{error.textContent='Unable to read this image. Try another file.';}};
  form.querySelectorAll('[data-expand-field]').forEach(button=>button.onclick=()=>expandField(button.dataset.expandField));
  form.onsubmit=e=>e.preventDefault();preview();
 }
 root.querySelectorAll('[data-builder-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.builderStep);renderStep();});
 root.querySelector('[data-builder-prev]').onclick=()=>{step=Math.max(0,step-1);renderStep();};
 root.querySelector('[data-builder-next]').onclick=()=>{if(step===steps.length-1)review();else{step++;renderStep();}};
 root.querySelector('[data-draft-save]').onclick=saveDraft;root.querySelector('[data-draft-review]').onclick=review;
 root.querySelector('[data-builder-preview-open]').onclick=()=>root.querySelector('.builder-preview').classList.add('is-open');root.querySelector('[data-builder-preview-toggle]').onclick=()=>root.querySelector('.builder-preview').classList.remove('is-open');
 root.querySelector('.builder-header>a').onclick=e=>{if(!dirty)return;e.preventDefault();h.show('<h2>Unsaved changes</h2><p>Save this private draft before leaving?</p><button class="shell-white-button" data-save-leave>Save and leave</button><button data-discard-leave>Leave without saving</button>');document.querySelector('[data-save-leave]').onclick=()=>{if(saveDraft())h.navigate('/my-title');};document.querySelector('[data-discard-leave]').onclick=()=>h.navigate('/my-title');};
 renderStep();return true;
}
